locked.scoped_css:
:root {
  --pi-paper: var(--wp-adapter-pi-paper);
  --pi-paper-deep: var(--wp-adapter-pi-paper-deep);
  --pi-paper-panel: var(--wp-adapter-pi-paper-panel);
  --pi-ink: var(--wp-adapter-pi-ink);
  --pi-ink-80: var(--wp-adapter-pi-ink-80);
  --pi-ink-70: var(--wp-adapter-pi-ink-70);
  --pi-ink-60: var(--wp-adapter-pi-ink-60);
  --pi-ink-55: var(--wp-adapter-pi-ink-55);
  --pi-ink-45: var(--wp-adapter-pi-ink-45);
  --pi-ink-30: var(--wp-adapter-pi-ink-30);
  --pi-data-1: var(--wp-adapter-pi-data-1);
  --pi-data-2: var(--wp-adapter-pi-data-2);
  --pi-data-3: var(--wp-adapter-pi-data-3);
  --pi-data-4: var(--wp-adapter-pi-data-4);
  --pi-data-5: var(--wp-adapter-pi-data-5);
  --pi-data-6: var(--wp-adapter-pi-data-6);
  --pi-sans: var(--wp-adapter-pi-font-sans);
  --pi-serif: var(--wp-adapter-pi-font-serif);
  --pi-mono: var(--wp-adapter-pi-font-mono);
  --pi-brush: var(--wp-adapter-pi-font-brush);
}

@scope (.slide[data-layout-id="paper-ink.relationship.R5"]) {
/* 卡片本体 724×488 fixed,比槽盒 1050×708 窄:由帧负责槽内摆位。
     以"齿轮+箭头"墨迹中心对齐页面正中 (960,540),并整体 1.2× 放大;
     组件母板与 viewBox 不动,眉题与页底 .caption 只作上下越界校验。 */
  .gears-host{position:absolute;left:435px;top:152px;width:1050px;height:708px;z-index:1}
  .gears-host>.pi-card{position:absolute;left:91px;top:65px;transform:scale(1.2);transform-origin:0 0;background:transparent}
  .gears-host .pi-art>text:first-of-type,
  .gears-host [data-field$="_desc"],
  .gears-host #r5-focus-en{font-size:13px}
  .caption{position:absolute;left:0;right:0;bottom:82px;text-align:center;font-family:var(--sans);font-size:var(--type-caption);letter-spacing:.04em;color:var(--ink);z-index:5}
.pi-card {
  width: 600px;
  min-height: 600px;
  background: var(--pi-paper);
  color: var(--pi-ink);
  font-family: var(--pi-sans);
  overflow: hidden;
  position: relative;
}
.pi-card > svg.pi-art {
  display: block;
  width: 100%;
  height: auto;
}
.pi-card text { user-select: none; }
.pi-metric-strip {
  box-sizing: border-box;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  align-items: stretch;
  width: min(1050px, 100%);
  min-height: 140px;
  border-top: 1.3px solid var(--pi-ink-80);
  border-bottom: .6px solid color-mix(in srgb, var(--pi-ink) 30%, transparent);
}
.pi-metric-strip [data-repeat-unit="metric"] {
  box-sizing: border-box;
  display: grid;
  align-content: center;
  justify-items: center;
  min-width: 0;
  padding: 14px 22px 12px;
  text-align: center;
}
.pi-metric-strip [data-repeat-unit="metric"] + [data-repeat-unit="metric"] {
  border-left: .6px solid color-mix(in srgb, var(--pi-ink) 30%, transparent);
}
.pi-metric-strip .pi-metric-value {
  font-family: var(--pi-serif);
  font-size: 42px;
  font-weight: var(--pi-weight-strong);
  line-height: 1;
}
.pi-metric-strip .pi-metric-label {
  margin-top: 10px;
  font-family: var(--pi-sans);
  font-size: 13px;
  font-weight: var(--pi-weight-regular);
  line-height: 1.2;
}
.pi-infra-kicker {
  color: var(--pi-ink-45);
  font-family: var(--pi-mono);
  font-size: 9px;
  letter-spacing: 2.6px;
}
.pi-infra-strip {
  box-sizing: border-box;
  display: grid;
  grid-template-rows: 34px 1fr;
  width: 1050px;
  min-height: 260px;
  padding: 12px 18px 14px;
  border: 1px dashed var(--pi-ink-45);
}
.pi-infra-head {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 20px;
}
.pi-infra-count {
  color: var(--pi-ink-45);
  font-family: var(--pi-mono);
  font-size: 8px;
  letter-spacing: 1.6px;
}
.pi-infra-items {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(135px, 1fr));
  gap: 12px;
  align-items: stretch;
}
.pi-infra-strip [data-repeat-unit="item"] {
  box-sizing: border-box;
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr);
  align-items: center;
  min-width: 0;
  padding: 8px 12px;
  border: .8px dashed color-mix(in srgb, var(--pi-ink) 52%, transparent);
  background: color-mix(in srgb, var(--pi-paper-panel) 52%, transparent);
}
.pi-infra-code {
  color: var(--pi-ink-45);
  font-family: var(--pi-mono);
  font-size: 8px;
  letter-spacing: .8px;
}
.pi-infra-label {
  min-width: 0;
  overflow: hidden;
  color: var(--pi-ink-70);
  font-family: var(--pi-sans);
  font-size: 11px;
  font-weight: 300;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* #061 对话标本：照 A1 源版 HTML/CSS，不用 SVG 描边冒充圆角。
   流式填充行为宿主（.pi-card 100%×100%），不自带固定宽高 */
.pi-chat-specimen {
  box-sizing: border-box;
  width: 100%;
  min-height: 0;
  background: var(--pi-paper-panel);
  border: 1px solid color-mix(in srgb, var(--pi-ink) 32%, transparent);
  border-radius: 18px;
  overflow: hidden;
}
.pi-chat-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 24px;
  border-bottom: 1px solid color-mix(in srgb, var(--pi-ink) 25%, transparent);
}
.pi-chat-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--pi-ink) 30%, transparent);
}
.pi-chat-bar-title {
  margin-left: 12px;
  color: var(--pi-ink-45);
  font-family: var(--pi-mono);
  font-size: 13px;
  letter-spacing: .25em;
}
.pi-chat-body { padding: 28px 32px 24px; }
.pi-chat-msg {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 24px;
}
.pi-chat-msg:last-child { margin-bottom: 0; }
.pi-chat-msg.is-user { flex-direction: row-reverse; }
.pi-chat-avatar {
  flex: none;
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  border: 1px solid color-mix(in srgb, var(--pi-ink) 38%, transparent);
  border-radius: 50%;
  background: var(--pi-paper-panel);
  font-family: var(--pi-sans);
  font-size: 15px;
  font-weight: 400;
}
.pi-chat-bub {
  max-width: 740px;
  padding: 16px 24px;
  border: 1px solid color-mix(in srgb, var(--pi-ink) 38%, transparent);
  border-radius: 16px;
  font-family: var(--pi-sans);
  font-size: 22px;
  font-weight: 300;
  line-height: 1.8;
}
.pi-chat-msg.is-user .pi-chat-bub {
  border-bottom-right-radius: 4px;
  background: var(--pi-paper-panel);
  font-weight: 400;
}
.pi-chat-msg.is-ai .pi-chat-bub { border-bottom-left-radius: 4px; }
.pi-chat-item {
  display: flex;
  gap: 12px;
  margin-top: 8px;
}
.pi-chat-pt {
  flex: none;
  padding-top: 12px;
  color: var(--pi-ink-45);
  font-size: 16px;
}
.pi-chat-score {
  font-family: var(--pi-mono);
  font-size: 26px;
  color: var(--pi-ink);
}
.pi-chat-note {
  color: var(--pi-ink-45);
  font-size: 18px;
}
.pi-chat-wrong {
  position: relative;
  display: inline-block;
  font-weight: 400;
}
.pi-chat-wrong::before,
.pi-chat-wrong::after {
  content: '';
  position: absolute;
  pointer-events: none;
  border: 1.1px solid var(--pi-ink);
  border-radius: 50%;
}
.pi-chat-wrong::before {
  inset: -4px -11px;
  transform: rotate(-4deg);
}
.pi-chat-wrong::after {
  inset: -6px -14px;
  border-width: .7px;
  opacity: .45;
  transform: rotate(6deg);
}
.pi-chat-specimen[data-message-count="5"] .pi-chat-body,
.pi-chat-specimen[data-message-count="6"] .pi-chat-body,
.pi-chat-specimen[data-message-count="7"] .pi-chat-body,
.pi-chat-specimen[data-message-count="8"] .pi-chat-body {
  padding: 18px 24px;
}
.pi-chat-specimen[data-message-count="5"] .pi-chat-msg,
.pi-chat-specimen[data-message-count="6"] .pi-chat-msg,
.pi-chat-specimen[data-message-count="7"] .pi-chat-msg,
.pi-chat-specimen[data-message-count="8"] .pi-chat-msg {
  gap: 12px;
  margin-bottom: 10px;
}
.pi-chat-specimen[data-message-count="5"] .pi-chat-avatar,
.pi-chat-specimen[data-message-count="6"] .pi-chat-avatar,
.pi-chat-specimen[data-message-count="7"] .pi-chat-avatar,
.pi-chat-specimen[data-message-count="8"] .pi-chat-avatar {
  width: 40px;
  height: 40px;
  font-size: 13px;
}
.pi-chat-specimen[data-message-count="5"] .pi-chat-bub,
.pi-chat-specimen[data-message-count="6"] .pi-chat-bub,
.pi-chat-specimen[data-message-count="7"] .pi-chat-bub,
.pi-chat-specimen[data-message-count="8"] .pi-chat-bub {
  padding: 9px 16px;
  font-size: 18px;
  line-height: 1.45;
}
}
